//! Built-in OpenMoji sticker catalogue (CC BY-SA 4.0, https://openmoji.org).
//!
//! The artwork and `catalog.json` are generated by `tools/import_openmoji.py`
//! and shipped as static files under `/stickers/openmoji/`, so they never
//! weigh on the sticker API. The catalogue is fetched once per session.

use std::{cell::RefCell, rc::Rc};

use serde::Deserialize;

use crate::{
    components::composer::fold,
    models::{ApiError, StickerItem},
    platform,
};

pub const CATALOG_PATH: &str = "/stickers/openmoji/catalog.json";
pub const HOME_URL: &str = "https://openmoji.org";
pub const LICENSE_URL: &str = "https://creativecommons.org/licenses/by-sa/4.0/";
pub const PACK_ID: &str = "openmoji";

/// (id, English label, cover hexcode).
#[derive(Clone, Debug, PartialEq, Deserialize)]
pub struct Category(pub String, pub String, pub String);

/// (hexcode, English name, category index, folded keywords separated by `|`).
#[derive(Clone, Debug, PartialEq, Deserialize)]
pub struct Item(pub String, pub String, pub usize, pub String);

#[derive(Clone, Debug, PartialEq, Deserialize)]
pub struct Catalog {
    pub source: String,
    pub license: String,
    pub categories: Vec<Category>,
    pub items: Vec<Item>,
}

thread_local! {
    static CACHE: RefCell<Option<Rc<Catalog>>> = const { RefCell::new(None) };
}

/// Hexcodes such as `1F600` or `1F1FB-1F1F3`; anything else is dropped.
pub fn valid_hex(h: &str) -> bool {
    !h.is_empty()
        && h.len() <= 80
        && h.split('-').all(|p| (4..=6).contains(&p.len()) && p.chars().all(|c| c.is_ascii_digit() || ('A'..='F').contains(&c)))
}

pub fn url(hex: &str) -> String {
    format!("/stickers/openmoji/{hex}.svg")
}

pub fn parse(body: &str) -> Option<Catalog> {
    let mut c: Catalog = serde_json::from_str(body).ok()?;
    let n = c.categories.len();
    c.categories.retain(|k| valid_hex(&k.2));
    if c.categories.len() != n {
        return None;
    }
    c.items.retain(|i| valid_hex(&i.0) && i.2 < n && !i.1.trim().is_empty());
    Some(c)
}

/// The catalogue if it was already loaded this session.
pub fn cached() -> Option<Rc<Catalog>> {
    CACHE.with(|c| c.borrow().clone())
}

pub async fn load() -> Result<Rc<Catalog>, ApiError> {
    if let Some(c) = CACHE.with(|c| c.borrow().clone()) {
        return Ok(c);
    }
    let (_, body) = platform::http_request("GET", CATALOG_PATH, None, None).await?;
    let catalog = Rc::new(parse(&body).ok_or(ApiError { code: "invalid_catalog".into(), status: 200 })?);
    CACHE.with(|c| *c.borrow_mut() = Some(catalog.clone()));
    Ok(catalog)
}

impl Item {
    pub fn url(&self) -> String {
        url(&self.0)
    }

    /// `q` must already be folded.
    pub fn matches(&self, q: &str) -> bool {
        fold(&self.1).contains(q) || self.3.contains(q)
    }

    pub fn as_sticker(&self) -> StickerItem {
        StickerItem {
            id: format!("om-{}", self.0),
            pack_id: PACK_ID.into(),
            name: self.1.clone(),
            file_url: self.url(),
            is_animated: false,
            created_at: String::new(),
        }
    }
}

impl Catalog {
    pub fn search(&self, query: &str, limit: usize) -> Vec<Item> {
        let q = fold(query.trim());
        if q.is_empty() {
            return Vec::new();
        }
        // Names that start with the query first, then any keyword match.
        let mut first: Vec<Item> = Vec::new();
        let mut rest: Vec<Item> = Vec::new();
        for it in &self.items {
            if fold(&it.1).starts_with(&q) {
                first.push(it.clone());
            } else if it.matches(&q) {
                rest.push(it.clone());
            }
            if first.len() >= limit {
                break;
            }
        }
        first.extend(rest);
        first.truncate(limit);
        first
    }

    /// Stickers for a short message that is exactly a name or keyword,
    /// e.g. "pizza", "mèo" or "cà phê". Generic words that fit too many
    /// stickers ("face", "cờ") suggest nothing.
    pub fn suggest(&self, text: &str, limit: usize) -> Vec<StickerItem> {
        let t = fold(text.trim());
        let t = t.trim_end_matches(['!', '.', '~', '?']).trim();
        if t.chars().count() < 2 || t.chars().count() > 30 || t.starts_with(['/', ':', '@']) {
            return Vec::new();
        }
        let by_name: Vec<&Item> = self.items.iter().filter(|i| fold(&i.1) == t).collect();
        let hits: Vec<&Item> = if !by_name.is_empty() {
            by_name
        } else {
            self.items.iter().filter(|i| i.3.split('|').any(|k| k == t)).collect()
        };
        if hits.len() > 16 {
            return Vec::new();
        }
        hits.into_iter().take(limit).map(Item::as_sticker).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"{"v":1,"source":"OpenMoji 17.0.0","license":"CC BY-SA 4.0",
        "categories":[["food","Food & Drink","1F355"],["nature","Animals & Nature","1F408"]],
        "items":[["1F355","Pizza",0,"food|cheese|banh pizza"],["2615","Hot beverage",0,"coffee|tea|ca phe|do uong nong"],
                 ["1F408","Cat",1,"pet|meo"],["1F431","Cat face",1,"face|pet|meo|mat meo"],
                 ["../x","Bad",0,""],["1F600","Grin",7,""]]}"#;

    #[test]
    fn parses_and_drops_bad_entries() {
        let c = parse(SAMPLE).unwrap();
        assert_eq!(c.items.len(), 4);
        assert!(valid_hex("1F1FB-1F1F3") && !valid_hex("1f600") && !valid_hex("1F600.svg") && !valid_hex(""));
        assert_eq!(c.items[0].url(), "/stickers/openmoji/1F355.svg");
    }

    #[test]
    fn search_and_suggest_use_folded_keywords() {
        let c = parse(SAMPLE).unwrap();
        assert_eq!(c.search("Cà phê", 10)[0].0, "2615");
        assert_eq!(c.search("cat", 10).len(), 2);
        let s = c.suggest("Mèo!", 8);
        assert_eq!(s.len(), 2);
        assert_eq!(s[0].file_url, "/stickers/openmoji/1F408.svg");
        assert_eq!(c.suggest("pizza", 8).len(), 1);
        assert!(c.suggest("hello there", 8).is_empty());
        assert!(c.suggest("/x", 8).is_empty());
    }
}
